발판을 밀어 올렸다 무릎이 과하게 모이지 않게 복귀.
발판을 “발로 차듯” 밀지 말고, 발 전체로 멀리 보낸다는 느낌으로 밀어요. 무릎은 발끝 방향을 따라갑니다.

